xpath.script:
document.addEventListener('DOMContentLoaded', function() {
console.log('DOM Content Loaded - Checking for student alert');

// Check if student ID was searched but no student data found
const urlParams = new URLSearchParams(window.location.search);
const studentId = urlParams.get('student_id');
const isTrainingPage = window.location.pathname.includes('training_page');
const hasStudentData = document.querySelector('.profile-section') !== null;

console.log('Student ID:', studentId);
console.log('Is Training Page:', isTrainingPage);
console.log('Has Student Data:', hasStudentData);

// If we're on training page, student ID was provided, but no student data found
if (isTrainingPage && studentId&& !hasStudentData) {
console.log('Showing student not found alert');
// Clear the navbar search field
const navbarInputs = document.querySelectorAll('.nexus-search-input');
navbarInputs.forEach(input => {
if (input) {
input.value = '';
}
});

// Show the alert after a short delay
setTimeout(() => {
showStudentNotFoundAlert();
}, 500);
}
});

// Student Not Found Alert Functions
function showStudentNotFoundAlert() {
console.log('Attempting to show student not found alert');
const alertElement = document.getElementById('studentNotFoundAlert');
if (alertElement) {
alertElement.classList.remove('d-none');
alertElement.classList.add('d-block');
showNotFoundScreen();
console.log('Student not found alert shown');
} else {
console.error('Student not found alert element not found');
}
}

function closeStudentNotFoundAlert() {
const alertElement = document.getElementById('studentNotFoundAlert');
if (alertElement) {
alertElement.classList.add('d-none');
alertElement.classList.remove('d-block');
}
}

// Screen Navigation Functions
function showNotFoundScreen() {
const notFoundScreen = document.getElementById('notFoundScreen');
const reenterScreen = document.getElementById('reenterScreen');
const contactScreen = document.getElementById('contactScreen');

if (notFoundScreen) notFoundScreen.classList.remove('d-none');
if (reenterScreen) reenterScreen.classList.add('d-none');
if (contactScreen) contactScreen.classList.add('d-none');
}

function showReenterForm() {
const notFoundScreen = document.getElementById('notFoundScreen');
const reenterScreen = document.getElementById('reenterScreen');
const contactScreen = document.getElementById('contactScreen');

if (notFoundScreen) notFoundScreen.classList.add('d-none');
if (reenterScreen) reenterScreen.classList.remove('d-none');
if (contactScreen) contactScreen.classList.add('d-none');

// Clear the input field and focus on it
setTimeout(() => {
const input = document.querySelector('#reenterScreen input[name="student_id"]');
if (input) {
input.value = ''; // Clear any previous value
input.focus();
}
}, 100);

// Clear URL parameters without reloading the page
if (window.history && window.history.replaceState) {
const url = new URL(window.location);
url.searchParams.delete('student_id');
window.history.replaceState({}, document.title, url.pathname);
}
}

function showContactInfo() {
const notFoundScreen = document.getElementById('notFoundScreen');
const reenterScreen = document.getElementById('reenterScreen');
const contactScreen = document.getElementById('contactScreen');

if (notFoundScreen) notFoundScreen.classList.add('d-none');
if (reenterScreen) reenterScreen.classList.add('d-none');
if (contactScreen) contactScreen.classList.remove('d-none');
}

function backToNotFound() {
showNotFoundScreen();
// Clear the re-enter form input when going back
const reenterInput = document.querySelector('#reenterScreen input[name="student_id"]');
if (reenterInput) {
reenterInput.value = '';
}
}

// Make functions globally available
window.showStudentNotFoundAlert = showStudentNotFoundAlert;
window.closeStudentNotFoundAlert = closeStudentNotFoundAlert;
window.showNotFoundScreen = showNotFoundScreen;
window.showReenterForm = showReenterForm;
window.showContactInfo = showContactInfo;
window.backToNotFound = backToNotFound;

body.script:
let currentButton = null;

// Original Custom Alert Functions
function showCustomAlert() {
document.getElementById('customAlert').classList.remove('d-none');
document.getElementById('customAlert').classList.add('d-block');
}

function showStudentId() {
document.getElementById('screenTwo').classList.remove('d-none');
document.getElementById('screenTwo').classList.add('d-block');
document.getElementById('screenOne').classList.remove('d-block');
document.getElementById('screenOne').classList.add('d-none');
}

function hideStudentId() {
document.getElementById('screenOne').classList.remove('d-none');
document.getElementById('screenOne').classList.add('d-block');
document.getElementById('screenTwo').classList.remove('d-block');
document.getElementById('screenTwo').classList.add('d-none');
}

function closeAlert() {
document.getElementById('customAlert').classList.add('d-none');
document.getElementById('customAlert').classList.remove('d-block');
}

// Show Student ID Required for guests
function showStudentIdRequired() {
// Clear any existing values first
clearAllSearchFields();

// Clear URL parameters
if (window.history && window.history.replaceState) {
const url = new URL(window.location);
url.searchParams.delete('student_id');
window.history.replaceState({}, document.title, url.pathname);
}

showStudentNotFoundAlert();
}

// Other functions
function loginRequired() {
alert('⚠️ Please login first to apply for this training course!');
if (confirm('Do you want to go to the login page now?')) {
window.location.href = '/web/login';
}
}

function applyDirect(button) {
var partnerId = button.getAttribute('data-partner-id');
var trainingId = button.getAttribute('data-training-id');
var courseCode = button.getAttribute('data-course-code');
var partnerName = button.getAttribute('data-partner-name');

var url = '/registration_for_training?partner_id=' + partnerId +
'&training_id=' + trainingId +
'&course_code=' + encodeURIComponent(courseCode) +
'&partner_name=' + encodeURIComponent(partnerName);

window.location.href = url;
}

function showLevelModal(button) {
currentButton = button;
document.getElementById('levelModal').classList.add('show');
}

function closeModal() {
document.getElementById('levelModal').classList.remove('show');
currentButton = null;
}

function continueApplication() {
if (currentButton) {
applyDirect(currentButton);
}
closeModal();
}

function applyAsNonStudent(button) {
if (confirm('ℹ️ You are not registered as a student. This may affect your application.
Continue?')) {
applyDirect(button);
}
}

// Close modal when clicking outside
document.addEventListener('click', function(event) {
const modal = document.getElementById('levelModal');
if (event.target === modal) {
closeModal();
}

// Close student not found modal when clicking outside
const studentModal = document.getElementById('studentNotFoundAlert');
if (studentModal && event.target === studentModal) {
closeStudentNotFoundAlert();
}

// Close custom alert when clicking outside
const customModal = document.getElementById('customAlert');
if (customModal && event.target === customModal) {
closeAlert();
}
});

// Enhanced search functionality
document.querySelectorAll('input[name="student_id"]').forEach(input => {
input.addEventListener('keyup', function(e) {
// Remove any non-alphanumeric characters and convert to uppercase
this.value = this.value.replace(/[^a-zA-Z0-9]/g, '').toUpperCase();
});

input.addEventListener('paste', function(e) {
setTimeout(() => {
this.value = this.value.replace(/[^a-zA-Z0-9]/g, '').toUpperCase();
}, 10);
});
});

document.querySelectorAll('.card-description').forEach(p => {
// default: clamp to 2 lines
p.style.display = '-webkit-box';
p.style.webkitBoxOrient = 'vertical';
p.style.webkitLineClamp = '2';
p.style.overflow = 'hidden';
p.style.textOverflow = 'ellipsis';
p.style.transition = 'all 0.2s ease-in-out';

// on hover: show full text
p.addEventListener('mouseenter', () => {
p.style.webkitLineClamp = 'unset';
p.style.overflow = 'visible';
});

// on leave: clamp again
p.addEventListener('mouseleave', () => {
p.style.webkitLineClamp = '2';
p.style.overflow = 'hidden';
});
});

xpath.script:
document.addEventListener('DOMContentLoaded', function() {
// Enhanced search input functionality
const searchInputs = document.querySelectorAll('.nexus-search-input, .nexus-hero-search-input');

searchInputs.forEach(input => {
// Auto-focus and select on click
input.addEventListener('click', function() {
this.select();
});

// Enhanced enter key handling
input.addEventListener('keypress', function(e) {
if (e.key === 'Enter') {
e.preventDefault();
this.closest('form').submit();
}
});

// Real-time validation
input.addEventListener('input', function() {
const value = this.value.trim();
const submitBtn = this.closest('form').querySelector('button[type="submit"]');

if (submitBtn) {
if (value.length > 0) {
submitBtn.style.opacity = '1';
submitBtn.style.transform = 'scale(1)';
} else {
submitBtn.style.opacity = '0.7';
submitBtn.style.transform = 'scale(0.95)';
}
}
});
});

// Smooth scroll to results
if (window.location.search.includes('student_id=')) {
const studentSection = document.querySelector('.nexus-student-section');
const trainingGrid = document.querySelector('.nexus-training-grid');

if (studentSection) {
setTimeout(() => {
studentSection.scrollIntoView({
behavior: 'smooth',
block: 'start'
});
}, 500);
} else if (trainingGrid) {
setTimeout(() => {
trainingGrid.scrollIntoView({
behavior: 'smooth',
block: 'start'
});
}, 500);
}
}

// Card hover effects
const trainingCards = document.querySelectorAll('.nexus-training-card');
trainingCards.forEach(card => {
card.addEventListener('mouseenter', function() {
this.style.transform = 'translateY(-15px) scale(1.02)';
});

card.addEventListener('mouseleave', function() {
this.style.transform = 'translateY(0) scale(1)';
});
});

// Apply button click tracking
const applyButtons = document.querySelectorAll('.nexus-apply-btn:not(.disabled)');
applyButtons.forEach(btn => {
btn.addEventListener('click', function(e) {
// Add loading state
const icon = this.querySelector('i');
const text = this.innerHTML;

if (icon && !this.classList.contains('loading')) {
this.classList.add('loading');
icon.className = 'fas fa-spinner fa-spin';

// Reset after navigation (fallback)
setTimeout(() => {
this.innerHTML = text;
this.classList.remove('loading');
}, 3000);
}
});
});

// Search suggestion (if needed)
const searchSuggestions = [
'101', '102', '103', '201', '202', '301'
];

searchInputs.forEach(input => {
input.addEventListener('focus', function() {
// Could add datalist or custom dropdown here
this.setAttribute('placeholder', 'e.g., 101, 102, 201...');
});

input.addEventListener('blur', function() {
this.setAttribute('placeholder', this.dataset.originalPlaceholder || 'Enter Student ID');
});
});
});
